/* Собрано tools/build.mjs из src/client.template.js и src/spellcore.mjs. Не править вручную. */
/**
 * Клиентская половина плагина проверки орфографии.
 *
 * Артефакт браузера: модуль регистрирует фабрику в window.__ModuleLoader__,
 * как требует загрузчик клиентских плагинов DSH. Внутрь вшиваются:
 *   - ядро проверки (src/spellcore.mjs, подставляется сборкой),
 *   - словарь ru_RU (.dic/.aff) в gzip+base64 (подставляется сборкой),
 *   - список частотных слов для порядка подсказок.
 *
 * Почему подсветка без изменения DOM:
 * чат рендерит React из журнала сессии, и вставка своих <span> внутрь
 * текстовых узлов ломает согласование (React владеет этими узлами). Поэтому
 * используется CSS Custom Highlight API: диапазоны (Range) подсвечиваются
 * псевдоэлементом ::highlight(), дерево остаётся нетронутым.
 *
 * Почему правка текста только визуальная:
 * сообщения в чате — неизменяемый журнал сессии, плагин не имеет права
 * переписывать его. Исправление применяется к показанному тексту (и
 * запоминается в рамках сессии), что и ожидает пользователь от «исправить
 * слово» в Word-подобном интерфейсе.
 */
window.__ModuleLoader__.load({
  id: 'dsh-spellcheck-ru',
  factory(require) {
    'use strict'

    // ------------------------------------------------------------------
    // Ядро проверки орфографии (вшивается сборкой из src/spellcore.mjs).
    // ------------------------------------------------------------------
    /**
 * Ядро проверки русской орфографии.
 *
 * Модуль намеренно не зависит от DOM и от React: он собирается в браузерный
 * артефакт плагина (см. tools/build.mjs) и одновременно импортируется
 * unit-тестами в Node. Поэтому здесь только чистые функции и структуры данных.
 *
 * Источник словаря: hunspell-совместимые файлы ru_RU.dic / ru_RU.aff
 * (LibreOffice/dictionaries, словарь russian-words, MIT). Мы НЕ разворачиваем
 * 146 тысяч основ в полный список форм (это миллионы строк и сотни мегабайт
 * памяти в браузере). Вместо этого применяется тот же алгоритм, что и в
 * hunspell: для проверяемого слова перебираются правила суффиксов (SFX),
 * восстанавливается основа, и она ищется в словаре основ с нужным флагом.
 *
 * Инварианты:
 *  - Состояние движка после создания неизменно, кроме кэшей (они не влияют
 *    на результат проверки, только на скорость).
 *  - `check` возвращает true для любого слова, которое словарь считает
 *    корректным, включая формы, полученные через SFX-правила.
 *  - `suggest` никогда не возвращает исходное слово и только слова, которые
 *    сам движок считает корректными (защита от «исправления» на опечатку).
 */

/** Минимальная длина слова, которое вообще рассматривается как проверяемое. */
const MIN_WORD_LENGTH = 3;

/** Максимальное расстояние Дамерау-Левенштейна для кандидатов в исправления. */
const MAX_SUGGEST_DISTANCE = 2;

/**
 * Порог частотности для слов с заглавной буквы.
 *
 * Слово с заглавной буквы — это либо начало предложения, либо имя или
 * название. Чтобы не подчёркивать фамилии и бренды («Нуриевым» → «Нутриевым»),
 * для таких слов требуем очень частотное исправление.
 */
const CAPITALIZED_RANK_LIMIT = 3000;

/**
 * Порог частотности для коротких исправлений (до 8 букв).
 *
 * Слова из частотного списка встречаются в живой речи, поэтому исправление
 * на них правдоподобно. Слова редких рангов (например «кыш», «теплой»,
 * «банд») — случайные соседи технических заимствований, их не принимаем.
 */
const TRUSTED_CANDIDATE_RANK_LIMIT = 15000;

/**
 * Порог частотности для совсем коротких исправлений (до 5 букв).
 *
 * Коротких слов в языке много, и рядом с любым заимствованием почти всегда
 * найдётся «сосед» из трёх букв («кэш» → «куш», «юнит» → «мнит»). Поэтому для
 * коротких кандидатов требуем действительно массовое слово.
 */
const SHORT_CANDIDATE_RANK_LIMIT = 3000;

/**
 * Гласные, которые путают при наборе.
 *
 * В русском ошибка в гласной — самый частый вид опечатки, и путают почти любые
 * гласные: «синию» вместо «синюю», «сабака» вместо «собака», «карова» вместо
 * «корова», «правельно» вместо «правильно». Поэтому все гласные считаем
 * взаимозаменяемыми, а отсекают мусор другие правила: кандидат должен быть
 * частотным словом (или длинным) и правдоподобным по согласным.
 */
const VOWELS = new Set(['а', 'е', 'ё', 'и', 'о', 'у', 'ы', 'э', 'ю', 'я']);

/** Пары согласных, которые путают на слух и при быстрой печати. */
const VOICING_PAIRS = [
  ['б', 'п'], ['в', 'ф'], ['г', 'к'], ['г', 'х'], ['д', 'т'],
  ['ж', 'ш'], ['з', 'с'], ['л', 'м'],
];

/** Ряды клавиатуры ЙЦУКЕН: соседние буквы в ряду путают при наборе. */
const KEYBOARD_ROWS = ['йцукенгшщзхъ', 'фывапролджэ', 'ячсмитьбю'];

/** Одинарная замена буквы правдоподобна для русской опечатки? */
function isPlausibleSubstitution(from, to) {
  if (from === to) return true;
  if (VOWELS.has(from) && VOWELS.has(to)) return true;
  for (const [first, second] of VOICING_PAIRS) {
    if ((from === first && to === second) || (from === second && to === first)) return true;
  }
  for (const row of KEYBOARD_ROWS) {
    const left = row.indexOf(from);
    const right = row.indexOf(to);
    if (left >= 0 && right >= 0 && Math.abs(left - right) === 1) return true;
  }
  return false;
}

/** Предел кэшей, чтобы долгая сессия не росла бесконечно. */
const CACHE_LIMIT = 20000;

/** Максимум кандидатов, попадающих в меню правой кнопки. */
const MAX_SUGGESTIONS = 8;

/**
 * Регэксп одного слова: только кириллица. Дефис и апостроф намеренно не
 * входят, поэтому «какой-то» распадается на два независимых слова — так
 * подчёркивание и подсказки относятся к конкретной части сложного слова.
 */
const TOKEN_RE = /[А-Яа-яЁё]+/gu;

/** Набор символов, которые считаются «буквами» при разборе условий в .aff. */
const CONDITION_SPECIAL = new Set(['[', ']', '.', '^', '-', '\\']);

/**
 * Разбить текст на слова с их позициями в исходной строке.
 * Позиции нужны, чтобы построить Range для подсветки (CSS Custom Highlight API
 * работает с диапазонами внутри текстовых узлов, а не с индексами в строке).
 * @param {string} text - содержимое текстового узла.
 * @returns {Array<{ word: string, start: number, end: number }>}
 */
function tokenize(text) {
  const result = [];
  if (!text) return result;
  TOKEN_RE.lastIndex = 0;
  let match;
  while ((match = TOKEN_RE.exec(text)) !== null) {
    result.push({ word: match[0], start: match.index, end: match.index + match[0].length });
  }
  return result;
}

/**
 * Привести «ё» к «е» для сравнения.
 *
 * Русскоязычные пользователи массово печатают «е» вместо «ё», и в чате это
 * не считается ошибкой. Нормализация применяется только при сравнении и
 * вычислении расстояния; показываем мы всегда словарную форму с «ё».
 * @param {string} word
 * @returns {string}
 */
function normalizeYo(word) {
  return word.replace(/ё/g, 'е').replace(/Ё/g, 'Е');
}

/**
 * Расстояние Дамерау-Левенштейна (вариант «optimal string alignment»).
 *
 * Реализация намеренно простая и без зависимостей: слова короткие (до ~30
 * символов), а вызывается функция только для кандидатов при подборе
 * исправлений. `limit` позволяет оборвать вычисление, если разница уже
 * заведомо больше допустимой — это заметно ускоряет перебор.
 * @param {string} a
 * @param {string} b
 * @param {number} limit - максимальное интересующее расстояние.
 * @returns {number} расстояние либо limit + 1, если оно больше лимита.
 */
function distance(a, b, limit = MAX_SUGGEST_DISTANCE) {
  if (a === b) return 0;
  if (Math.abs(a.length - b.length) > limit) return limit + 1;
  const n = a.length;
  const m = b.length;
  // prev2/prev1/current — три строки матрицы; памяти O(m), а не O(n*m).
  let prev2 = new Array(m + 1).fill(0);
  let prev1 = new Array(m + 1).fill(0);
  let current = new Array(m + 1).fill(0);
  for (let j = 0; j <= m; j += 1) prev1[j] = j;
  for (let i = 1; i <= n; i += 1) {
    current[0] = i;
    let rowMin = current[0];
    for (let j = 1; j <= m; j += 1) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      let value = Math.min(prev1[j] + 1, current[j - 1] + 1, prev1[j - 1] + cost);
      // Перестановка соседних символов — самая частая опечатка при быстрой печати.
      if (i > 1 && j > 1
        && a.charCodeAt(i - 1) === b.charCodeAt(j - 2)
        && a.charCodeAt(i - 2) === b.charCodeAt(j - 1)) {
        value = Math.min(value, prev2[j - 2] + 1);
      }
      current[j] = value;
      if (value < rowMin) rowMin = value;
    }
    if (rowMin > limit) return limit + 1;
    const recycled = prev2;
    prev2 = prev1;
    prev1 = current;
    current = recycled;
  }
  return prev1[m];
}

/**
 * Положить значение в кэш, не давая ему расти бесконечно.
 *
 * При переполнении выбрасывается самый старый ключ (Map хранит порядок
 * вставки), а не весь кэш: полная очистка в долгой сессии означала бы
 * повторный дорогой пересчёт всех слов чата.
 * @param {Map<string, unknown>} cache
 * @param {string} key
 * @param {unknown} value
 */
function remember(cache, key, value) {
  if (cache.size >= CACHE_LIMIT) {
    const oldest = cache.keys().next();
    if (!oldest.done) cache.delete(oldest.value);
  }
  cache.set(key, value);
}

/**
 * Разобрать .aff: TRY-алфавит и правила суффиксов.
 *
 * Формат строк: заголовок блока `SFX флаг перекрёстный количество`, затем
 * правила `SFX флаг отрезать приписать условие`. Условие — упрощённый
 * шаблон hunspell: литералы, `.` (любой символ) и классы `[...]`.
 * @param {string} text
 * @returns {{ tryChars: string, rules: Array<{flag:string,strip:string,append:string,condition:RegExp|null,cross:boolean}>, maxAppend: number }}
 */
function parseAff(text) {
  const rules = [];
  let tryChars = '';
  let maxAppend = 0;
  const lines = text.split(/\r?\n/u);
  /** @type {Map<string, boolean>} флаг → перекрёстность (PFX+SFX), для полноты */
  const crossFlags = new Map();
  for (const raw of lines) {
    if (!raw) continue;
    if (raw.startsWith('TRY ')) {
      tryChars = raw.slice(4).trim();
      continue;
    }
    if (!raw.startsWith('SFX ') && !raw.startsWith('PFX ')) continue;
    const parts = raw.trim().split(/\s+/u);
    if (parts.length < 4) continue;
    const [, flag, third, fourth] = parts;
    // Заголовок блока: третий токен Y/N, четвёртый — число правил.
    if ((third === 'Y' || third === 'N') && /^\d+$/u.test(fourth)) {
      crossFlags.set(flag, third === 'Y');
      continue;
    }
    const strip = third === '0' ? '' : third;
    const append = fourth === '0' ? '' : fourth;
    const conditionText = parts.length >= 5 ? parts[4] : '';
    const condition = conditionText === '' || conditionText === '.' ? null : compileCondition(conditionText);
    rules.push({ flag, strip, append, condition, cross: crossFlags.get(flag) === true });
    if (append.length > maxAppend) maxAppend = append.length;
  }
  return { tryChars, rules, maxAppend };
}

/**
 * Превратить условие hunspell в регулярное выражение «конец основы».
 *
 * Примеры из ru_RU.aff: `чь`, `[лнртв]ый`, `[цс]кий`, `заться`.
 * Спецсимволы aside, шаблон применяется именно к концу основы словаря —
 * так же, как это делает hunspell при развёртывании аффиксов.
 * @param {string} pattern
 * @returns {RegExp}
 */
function compileCondition(pattern) {
  let source = '';
  for (let i = 0; i < pattern.length; i += 1) {
    const ch = pattern[i];
    if (ch === '[') {
      // Класс символов копируем как есть: внутри допустимы диапазоны и ^.
      const close = pattern.indexOf(']', i + 1);
      if (close < 0) {
        source += '\\[';
        continue;
      }
      source += pattern.slice(i, close + 1);
      i = close;
      continue;
    }
    if (ch === '.') {
      source += '.';
      continue;
    }
    source += CONDITION_SPECIAL.has(ch) ? `\\${ch}` : ch.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
  }
  try {
    return new RegExp(`${source}$`, 'u');
  } catch {
    // Некорректное условие в словаре не должно валить весь движок:
    // правило станет «слишком строгим» и просто не сработает.
    return /$a/u;
  }
}

/**
 * Разобрать .dic: основа → строка флагов.
 * Первая строка файла — количество записей, она пропускается.
 * @param {string} text
 * @returns {Map<string, string>}
 */
function parseDic(text) {
  const stems = new Map();
  const lines = text.split(/\r?\n/u);
  for (let i = 1; i < lines.length; i += 1) {
    const line = lines[i];
    if (!line) continue;
    const slash = line.indexOf('/');
    if (slash < 0) stems.set(line, '');
    else stems.set(line.slice(0, slash), line.slice(slash + 1));
  }
  return stems;
}

/**
 * Создать движок проверки.
 *
 * @param {object} options
 * @param {string} options.dic - содержимое .dic (UTF-8).
 * @param {string} options.aff - содержимое .aff (UTF-8).
 * @param {Iterable<string>} [options.userWords] - пользовательские слова.
 * @param {Iterable<string>} [options.ignore] - пропущенные слова.
 * @param {Iterable<string>} [options.frequency] - слова в порядке убывания частоты
 *   (индекс = ранг). Нужен только для порядка подсказок: среди кандидатов с
 *   одинаковым расстоянием выше поднимается частотное слово.
 */
function createEngine(options) {
  const stems = parseDic(options.dic);
  const { tryChars, rules, maxAppend } = parseAff(options.aff);
  /** @type {Map<string, number>} слово → ранг частоты (0 — самое частое). */
  const frequencyRank = new Map();
  if (options.frequency) {
    let rank = 0;
    for (const word of options.frequency) {
      const key = normalizeYo(String(word).toLowerCase());
      if (!frequencyRank.has(key)) frequencyRank.set(key, rank);
      rank += 1;
    }
  }

  /** @type {Map<string, Array<{flag:string,strip:string,append:string,condition:RegExp|null}>>} */
  const rulesByAppend = new Map();
  /** @type {Map<string, Array<{strip:string,append:string,condition:RegExp|null}>>} */
  const rulesByFlag = new Map();
  for (const rule of rules) {
    let byAppend = rulesByAppend.get(rule.append);
    if (!byAppend) rulesByAppend.set(rule.append, byAppend = []);
    byAppend.push(rule);
    let byFlag = rulesByFlag.get(rule.flag);
    if (!byFlag) rulesByFlag.set(rule.flag, byFlag = []);
    byFlag.push(rule);
  }

  const userWords = new Set([...(options.userWords ?? [])].map(word => word.toLowerCase()));
  const ignoreWords = new Set([...(options.ignore ?? [])].map(word => word.toLowerCase()));

  /** Алфавит для генерации вариантов: TRY-строка hunspell + «ё» (её там нет). */
  const alphabet = [...new Set(`${tryChars.toLowerCase()}ё`)].filter(ch => /[а-яё]/u.test(ch));

  const checkCache = new Map();
  const suggestCache = new Map();
  const flagCache = new Map();

  // Список основ в отсортированном виде нужен только для подбора исправлений
  // по префиксу; строим лениво, чтобы не платить за сортировку там, где
  // подсказки ни разу не понадобились (например, в тексте без опечаток).
  let sortedStems = null;

  /**
   * Проверка сырой словоформы по правилам суффиксов (без учёта регистра).
   * @param {string} word
   * @returns {boolean}
   */
  const matchesRules = (word) => {
    if (stems.has(word)) return true;
    const len = word.length;
    for (let appendLength = 0; appendLength <= maxAppend && appendLength <= len; appendLength += 1) {
      const append = appendLength === 0 ? '' : word.slice(len - appendLength);
      const candidates = rulesByAppend.get(append);
      if (!candidates) continue;
      const base = word.slice(0, len - appendLength);
      for (const rule of candidates) {
        const stem = rule.strip ? base + rule.strip : base;
        const flags = stems.get(stem);
        if (flags === undefined) continue;
        if (!flags.includes(rule.flag)) continue;
        if (rule.condition !== null && !rule.condition.test(stem)) continue;
        return true;
      }
    }
    return false;
  };

  /**
   * Проверить слово с учётом регистра, «ё» и пользовательских слов.
   * @param {string} word
   * @returns {boolean}
   */
  const checkUncached = (word) => {
    if (word.length < 1) return true;
    const lower = word.toLowerCase();
    if (userWords.has(lower)) return true;
    if (ignoreWords.has(lower)) return true;
    const variants = new Set([word, lower]);
    // Заглавная буква в начале предложения и имена собственные не должны
    // считаться ошибкой, если словарная форма начинается со строчной — и наоборот.
    variants.add(lower.charAt(0).toUpperCase() + lower.slice(1));
    variants.add(normalizeYo(word));
    variants.add(normalizeYo(lower));
    for (const variant of variants) {
      if (matchesRules(variant)) return true;
    }
    return false;
  };

  /**
   * Проверить слово (с кэшем).
   * @param {string} word
   * @returns {boolean}
   */
  const check = (word) => {
    const cached = checkCache.get(word);
    if (cached !== undefined) return cached;
    const result = checkUncached(word);
    remember(checkCache, word, result);
    return result;
  };

  /** Привести основу к нижнему регистру для бинарного поиска по массиву. */
  const stemKeys = () => {
    if (sortedStems === null) {
      sortedStems = [];
      for (const stem of stems.keys()) sortedStems.push(stem);
      sortedStems.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    }
    return sortedStems;
  };

  /**
   * Развернуть одну основу в словоформы по её флагам.
   * Используется только для подбора исправлений, поэтому ограничено по объёму.
   * @param {string} stem
   * @param {string} flags
   * @param {Set<string>} sink
   */
  const expandStem = (stem, flags, sink) => {
    sink.add(stem);
    if (!flags) return;
    for (const flag of flags) {
      const list = rulesByFlag.get(flag);
      if (!list) continue;
      for (const rule of list) {
        if (rule.strip && !stem.endsWith(rule.strip)) continue;
        if (rule.condition !== null && !rule.condition.test(stem)) continue;
        const form = (rule.strip ? stem.slice(0, stem.length - rule.strip.length) : stem) + rule.append;
        if (form.length > 1) sink.add(form);
      }
    }
  };

  /**
   * Собрать словоформы основ, начинающихся с заданного префикса.
   * @param {string} prefix - префикс в нижнем регистре.
   * @param {number} maxStems - предел числа просматриваемых основ.
   * @param {Set<string>} sink
   */
  const collectByPrefix = (prefix, maxStems, sink) => {
    if (prefix.length < 2) return;
    const keys = stemKeys();
    let low = 0;
    let high = keys.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (keys[mid] < prefix) low = mid + 1;
      else high = mid;
    }
    let seen = 0;
    for (let i = low; i < keys.length && seen < maxStems; i += 1) {
      const stem = keys[i];
      if (!stem.toLowerCase().startsWith(prefix)) break;
      expandStem(stem, stems.get(stem) ?? '', sink);
      seen += 1;
    }
  };

  /**
   * Кандидаты с одной правкой: удаление, перестановка, замена, вставка.
   *
   * Это дешёвый источник (около 500 проверок для слова из 8 букв), и именно он
   * закрывает большинство реальных опечаток. Порядок перебора — TRY-строка
   * словаря, то есть частотный порядок букв языка.
   * @param {string} lower - слово в нижнем регистре.
   * @param {Set<string>} sink
   */
  const collectEditCandidates = (lower, sink) => {
    const length = lower.length;
    if (length < 2) return;
    for (let i = 0; i < length; i += 1) {
      sink.add(lower.slice(0, i) + lower.slice(i + 1));
      if (i + 1 < length) {
        sink.add(lower.slice(0, i) + lower.charAt(i + 1) + lower.charAt(i) + lower.slice(i + 2));
      }
      for (const ch of alphabet) {
        sink.add(lower.slice(0, i) + ch + lower.slice(i + 1));
        sink.add(lower.slice(0, i) + ch + lower.slice(i));
      }
    }
  };

  /**
   * Вес правдоподобия опечатки: 0 — правдоподобная (перестановка или
   * гласная/соседняя клавиша/путаница звонкости), 1 — сомнительная замена.
   *
   * Гласные в русском слове взаимозаменяемы («сабака» ↔ «собака»), поэтому
   * они дают вес 0 даже для замены, а вот согласные — только на соседних
   * клавишах или в паре звонкости. Иначе «кэш» → «куш» и «Сбера» → «сбора»
   * выглядели бы как настоящие опечатки.
   * @param {string} typo - нижний регистр.
   * @param {string} candidate - нижний регистр.
   * @returns {number}
   */
  const plausibilityWeight = (typo, candidate) => {
    if (typo.length !== candidate.length) return 0;
    const differing = [];
    for (let i = 0; i < typo.length; i += 1) {
      if (typo[i] !== candidate[i]) differing.push(i);
    }
    if (differing.length === 0) return 0;
    // Перестановка соседних букв — обычная опечатка.
    if (differing.length === 2) return 0;
    if (differing.length > 2) return 1;
    const position = differing[0];
    return isPlausibleSubstitution(typo[position], candidate[position]) ? 0 : 1;
  };

  /**
   * Подобрать исправления для слова.
   *
   * Два независимых источника кандидатов:
   *  1) все варианты с одной правкой — закрывает обычные опечатки;
   *  2) словоформы словарных основ, близких по префиксу — закрывает ошибки в
   *     окончаниях и морфологические опечатки, где нужно две правки. Этот
   *     источник заметно дороже, поэтому в фоновой проверке текста он не
   *     используется (см. shouldFlag), а нужен для меню правой кнопки.
   * @param {string} word
   * @param {boolean} deep - включать поиск по морфологическому окружению.
   * @returns {Array<{ word: string, distance: number }>} до MAX_SUGGESTIONS вариантов.
   */
  const suggestUncached = (word, deep) => {
    const lower = word.toLowerCase();
    const target = normalizeYo(lower);
    /** @type {Set<string>} */
    const candidates = new Set();
    collectEditCandidates(lower, candidates);
    if (deep) {
      const neighborhoods = new Set();
      for (const cut of [target.length, target.length - 1, target.length - 2]) {
        if (cut < 2) continue;
        collectByPrefix(target.slice(0, cut), 40, neighborhoods);
      }
      for (const form of neighborhoods) candidates.add(form);
    }

    /** @type {Array<{ word: string, distance: number, weight: number }>} */
    const scored = [];
    for (const candidate of candidates) {
      if (!candidate || candidate === lower) continue;
      if (!check(candidate)) continue;
      const d = distance(target, normalizeYo(candidate), MAX_SUGGEST_DISTANCE);
      if (d > MAX_SUGGEST_DISTANCE) continue;
      // Расстояние 0 после нормализации «ё» означает, что это то же слово,
      // просто с другой буквой ё — подсказывать такое бессмысленно.
      if (d === 0) continue;
      // Вес правдоподобия считается только для одной правки: на двух правках
      // любая замена выглядит «объяснимой».
      const weight = d === 1 ? plausibilityWeight(target, normalizeYo(candidate)) : 0;
      scored.push({ word: candidate, distance: d, weight });
    }
    // Сортировка: правдоподобие опечатки (иначе «карова» исправлялась бы в
    // «какова»), затем расстояние, затем частотность, затем близость длины,
    // затем алфавит как стабильный детерминированный тай-брейкер.
    const rankOf = candidate => frequencyRank.get(normalizeYo(candidate)) ?? Number.MAX_SAFE_INTEGER;
    scored.sort((a, b) => a.weight - b.weight
      || a.distance - b.distance
      || rankOf(a.word) - rankOf(b.word)
      || Math.abs(a.word.length - lower.length) - Math.abs(b.word.length - lower.length)
      || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0));

    const unique = [];
    const seen = new Set();
    for (const item of scored) {
      // «Дела» и «дёла» — одно и то же слово для пользователя: ключ без «ё».
      const key = normalizeYo(item.word);
      if (seen.has(key)) continue;
      seen.add(key);
      unique.push(item);
      if (unique.length >= MAX_SUGGESTIONS) break;
    }
    return unique;
  };

  /**
   * Подобрать исправления (с кэшем), восстановив регистр исходного слова.
   * @param {string} word
   * @param {{ deep?: boolean }} [options]
   * @returns {Array<{ word: string, distance: number }>}
   */
  const suggest = (word, options = {}) => {
    const deep = options.deep !== false;
    const cacheKey = `${deep ? 'd' : 's'}:${word}`;
    const cached = suggestCache.get(cacheKey);
    if (cached !== undefined) return cached;
    const raw = suggestUncached(word, deep);
    const isUpper = word === word.toUpperCase();
    const isCapitalized = !isUpper && word.charAt(0) !== word.charAt(0).toLowerCase();
    const result = raw.map((item) => {
      let display = item.word;
      if (isUpper) display = display.toUpperCase();
      else if (isCapitalized) display = display.charAt(0).toUpperCase() + display.slice(1);
      return { word: display, distance: item.distance };
    });
    if (suggestCache.size >= CACHE_LIMIT) suggestCache.delete(suggestCache.keys().next().value);
    suggestCache.set(cacheKey, result);
    return result;
  };

  /**
   * Нужно ли подчёркивать слово.
   *
   * Словарь не содержит все имена, термины и неологизмы, поэтому «слова нет в
   * словаре» само по себе не повод рисовать красную волну. Подчёркиваем только
   * когда рядом есть правдоподобное словарное исправление с расстоянием 1 —
   * это резко снижает число ложных срабатываний на именах собственных и
   * технических терминах. Проверка идёт по дешёвому набору кандидатов
   * (одна правка), потому что вызывается для каждого незнакомого слова при
   * каждом обновлении текста.
   * @param {string} word
   * @returns {boolean}
   */
  const shouldFlag = (word) => {
    const cached = flagCache.get(word);
    if (cached !== undefined) return cached;
    const result = decideFlag(word);
    if (flagCache.size >= CACHE_LIMIT) flagCache.delete(flagCache.keys().next().value);
    flagCache.set(word, result);
    return result;
  };

  /**
   * Решение о подчёркивании без кэша (см. shouldFlag).
   * @param {string} word
   * @returns {boolean}
   */
  const decideFlag = (word) => {
    if (!isCheckableWord(word)) return false;
    if (check(word)) return false;
    const raw = suggestUncached(word, false);
    // Нужен хотя бы один правдоподобный кандидат с одной правкой, и этому
    // кандидату нужно доверять:
    //  - длинное слово (8+ букв) принимаем и без частотного списка, иначе
    //    теряются опечатки в терминах («отабражение» → «отображение»);
    //  - короткое (до 5 букв) — только массовое слово, иначе рядом с любым
    //    заимствованием находится случайный «сосед» («кэш» → «куш»);
    //  - среднее — частотное слово из списка.
    const trusted = (candidate) => {
      if (candidate.length >= 8) return true;
      const rank = frequencyRank.get(normalizeYo(candidate));
      if (rank === undefined) return false;
      return rank <= (candidate.length < 5 ? SHORT_CANDIDATE_RANK_LIMIT : TRUSTED_CANDIDATE_RANK_LIMIT);
    };
    const plausible = raw.filter(item => item.distance === 1 && item.weight === 0 && trusted(item.word));
    if (plausible.length === 0) return false;
    const isCapitalized = word.charAt(0) !== word.charAt(0).toLowerCase();
    if (!isCapitalized) return true;
    // Слово с заглавной буквы — вероятное имя или название. Требуем, чтобы
    // хотя бы одно правдоподобное исправление было частотным словом:
    // «Пажалуйста» → «пожалуйста» проходит, «Нуриевым» → «Нутриевым» — нет.
    return plausible.some((item) => {
      const rank = frequencyRank.get(normalizeYo(item.word));
      return rank !== undefined && rank < CAPITALIZED_RANK_LIMIT;
    });
  };

  /**
   * Добавить слово в пользовательский словарь (после «Добавить в словарь»).
   * Кэши сбрасываются целиком: слово могло быть в них помечено как ошибочное.
   * @param {string} word
   */
  const addUserWord = (word) => {
    const lower = word.toLowerCase();
    if (userWords.has(lower)) return;
    userWords.add(lower);
    checkCache.clear();
    suggestCache.clear();
    flagCache.clear();
  };

  /**
   * Больше не считать слово ошибочным в этой сессии.
   * @param {string} word
   */
  const addIgnored = (word) => {
    const lower = word.toLowerCase();
    if (ignoreWords.has(lower)) return;
    ignoreWords.add(lower);
    checkCache.clear();
    suggestCache.clear();
    flagCache.clear();
  };

  return {
    check,
    suggest,
    shouldFlag,
    addUserWord,
    addIgnored,
    stats: () => ({ stems: stems.size, rules: rules.length, alphabet: alphabet.length }),
  };
}

/**
 * Годится ли токен для проверки орфографии.
 *
 * Отсекаем то, что заведомо не является русским словом: аббревиатуры,
 * идентификаторы с цифрами, camelCase, слишком короткие токены.
 * @param {string} word
 * @returns {boolean}
 */
function isCheckableWord(word) {
  if (word.length < MIN_WORD_LENGTH) return false;
  if (!/^[А-Яа-яЁё]+$/u.test(word)) return false;
  // Аббревиатуры и названия вида ВШЭ, ИТ — не проверяем.
  if (word === word.toUpperCase()) return false;
  // Внутренние заглавные буквы — это идентификатор, а не слово.
  const tail = word.slice(1);
  if (tail !== tail.toLowerCase() && tail !== tail.toUpperCase()) return false;
  return true;
}

/**
 * Применить исправление к строке по позициям токена.
 * Чистая функция: используется и подсветкой, и тестами.
 * @param {string} text
 * @param {number} start
 * @param {number} end
 * @param {string} replacement
 * @returns {string}
 */
function replaceRange(text, start, end, replacement) {
  return text.slice(0, start) + replacement + text.slice(end);
}

    // ------------------------------------------------------------------
    // Данные словаря (вшиваются сборкой: gzip + base64).
    // ------------------------------------------------------------------
    const DIC_GZ_BASE64 = ''
    const AFF_GZ_BASE64 = ''
    const FREQ_GZ_BASE64 = ''

    /** Пространство имён переводов плагина. */
    const NAMESPACE = 'dshSpellcheck'
    /** Имя семейства целей контекстного меню: своё, чтобы не пересечься с хостом. */
    const TARGET_KIND = 'dshSpellcheckWord'
    /** Имя набора подсветки CSS Custom Highlight API. */
    const HIGHLIGHT_NAME = 'dsh-spellcheck-error'
    /** Контейнер чата, который размещает хост (см. ConversationContent.tsx). */
    const CHAT_REGION_SELECTOR = '[data-conversation-region="chat"]'
    /**
     * Поле ввода композера: contenteditable, который принадлежит Lexical.
     *
     * Проверять его тоже нужно — пользователь печатает именно там. Текст
     * подсвечивается через CSS Custom Highlight API (без изменения DOM), а
     * замена слова вставляется штатной командой редактирования, чтобы модель
     * Lexical осталась согласованной.
     */
    const COMPOSER_INPUT_SELECTOR = '[data-composer-input]'
    /** Узлы, внутри которых проверять орфографию бессмысленно или опасно. */
    const SKIP_SELECTOR = [
      'pre', 'code', 'kbd', 'samp', 'script', 'style', 'textarea', 'input',
      'select', 'option', '[contenteditable="false"]', '[data-spellcheck-skip]',
    ].join(',')
    /** Ключ localStorage с пользовательским словарём. */
    const STORAGE_USER = 'dsh.spellcheck.userWords'
    /** Минимальный интервал между пересканированиями текста, мс. */
    const SCAN_INTERVAL_MS = 120
    /** Сколько вариантов замены показывать в меню (остальные не влезают в экран). */
    const MAX_MENU_SUGGESTIONS = 5

    /** Переводы: en и zh — базовые локали DSH, ru — язык пользователя. */
    const DICTIONARIES = {
      en: {
        suggestHeader: 'Replace with',
        addToDictionary: 'Add to dictionary',
        ignoreSession: 'Ignore until reload',
        fixedNotice: 'Word corrected',
        undo: 'Undo',
        failed: 'Action failed',
        unavailable: 'Spell checker is still loading',
      },
      ru: {
        suggestHeader: 'Заменить на',
        addToDictionary: 'Добавить в словарь',
        ignoreSession: 'Пропустить до перезагрузки',
        fixedNotice: 'Слово исправлено',
        undo: 'Отменить',
        failed: 'Не удалось выполнить действие',
        unavailable: 'Проверка орфографии ещё загружается',
      },
      zh: {
        suggestHeader: '替换为',
        addToDictionary: '添加到词典',
        ignoreSession: '刷新前忽略',
        fixedNotice: '已修正单词',
        undo: '撤销',
        failed: '操作失败',
        unavailable: '拼写检查仍在加载',
      },
    }

    // ------------------------------------------------------------------
    // Вспомогательные функции (не зависят от состояния плагина).
    // ------------------------------------------------------------------

    /** Прочитать JSON из localStorage, не падая на испорченном значении. */
    function readStoredList(key) {
      try {
        const raw = window.localStorage.getItem(key)
        if (!raw) return []
        const parsed = JSON.parse(raw)
        return Array.isArray(parsed) ? parsed.filter(item => typeof item === 'string') : []
      } catch {
        return []
      }
    }

    /** Записать список в localStorage; недоступное хранилище не ломает плагин. */
    function writeStoredList(key, list) {
      try {
        window.localStorage.setItem(key, JSON.stringify(list))
      } catch {
        // Приватный режим или запрет хранилища — работаем без сохранения.
      }
    }

    /** base64 → байты (atob есть в браузере, Buffer в бандле недоступен). */
    function base64ToBytes(base64) {
      const binary = window.atob(base64)
      const bytes = new Uint8Array(binary.length)
      for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
      return bytes
    }

    /**
     * Распаковать gzip и вернуть текст.
     * DecompressionStream есть в Chromium (Electron), но проверяем явно:
     * без него плагин обязан молча выключиться, а не падать с исключением
     * внутри чужого React-дерева.
     */
    async function gunzipText(base64) {
      if (typeof DecompressionStream !== 'function') {
        throw new Error('DecompressionStream is unavailable')
      }
      const bytes = base64ToBytes(base64)
      const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))
      return await new Response(stream).text()
    }

    /** Подогнать регистр замены под исходное слово. */
    function matchCase(original, replacement) {
      if (original === original.toUpperCase()) return replacement.toUpperCase()
      const first = original.charAt(0)
      if (first !== first.toLowerCase()) return replacement.charAt(0).toUpperCase() + replacement.slice(1)
      return replacement.charAt(0).toLowerCase() + replacement.slice(1)
    }

    /** Ключ сравнения слов: без регистра и с «е» вместо «ё». */
    function wordKey(word) {
      return normalizeYo(word.toLowerCase())
    }

    // ------------------------------------------------------------------
    // Плагин.
    // ------------------------------------------------------------------
    // Ссылка на объект плагина нужна отладочному контракту: внутри метода
    // apply() собственного имени у функции нет.
    let pluginHandle = null
    const plugin = {
      inject: ['contextMenus', 'locale'],
      apply(ctx) {
        /** @type {null | ReturnType<typeof createEngine>} */
        let engine = null
        /** @type {Promise<void> | null} */
        let engineLoading = null
        /** Последнее исправление — для кнопки «Отменить» в уведомлении. */
        let lastFix = null
        /**
         * Открытые вхождения слов: id → текстовый узел и смещения.
         *
         * Меню хоста получает только JSON-совместимую цель ({ word, occurrence }),
         * поэтому сам узел живёт здесь. Так действие применяется именно к тому
         * месту, где кликнули, даже если за время показа меню кликнули ещё раз.
         */
        const occurrences = new Map()
        let occurrenceSeq = 0
        /** Последний открытый жест: защита от двойного открытия меню. */
        let lastOpen = { word: '', at: 0 }
        /**
         * Текстовые узлы → снимок текста и диапазоны (кэш между сканами).
         * Пересоздаётся, когда нужно сбросить кэш целиком: WeakMap нельзя очистить.
         */
        let nodeCache = new WeakMap()
        /** Ставился ли уже набор подсветки (чтобы не пересчитывать её без изменений). */
        let painted = false
        let scanTimer = 0
        /** Хэндл отложенной загрузки словаря: снимается при выгрузке плагина. */
        let loadTimer = 0
        /** Исходное значение spellcheck у полей ввода, которым мы его отключили. */
        const nativeSpellingDisabled = new Map()
        let announcedSpellingOff = false
        let lastScanAt = 0
        let observer = null
        let disposed = false
        let warnedUnsupported = false
        const userWords = new Set(readStoredList(STORAGE_USER).map(word => word.toLowerCase()))
        const ignoredWords = new Set()

        const t = ctx.locale.bind(NAMESPACE)

        /** Сбросить кэш диапазонов (после смены настроек или словаря). */
        const resetNodeCache = () => {
          nodeCache = new WeakMap()
          painted = false
        }

        /** Есть ли в среде CSS Custom Highlight API. */
        const highlightSupported = () => typeof CSS !== 'undefined' && CSS.highlights
          && typeof window.Highlight === 'function'

        const styleElement = document.createElement('style')
        styleElement.setAttribute('data-dsh-spellcheck', '')
        // Подчёркивание рисуется поверх текста, не меняя разметку. Цвет берётся
        // из семантического токена темы, с запасным значением на случай
        // переименования токена в новой версии DSH.
        styleElement.textContent = `::highlight(${HIGHLIGHT_NAME}) {
  text-decoration-line: underline;
  text-decoration-style: wavy;
  text-decoration-color: var(--dsw-alias-state-error-primary, #e5484d);
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
  text-decoration-skip-ink: none;
  background-color: color-mix(in srgb, var(--dsw-alias-state-error-primary, #e5484d) 12%, transparent);
}`

        /** Загрузить словарь один раз; повторные вызовы ждут тот же промис. */
        const ensureEngine = () => {
          if (engine !== null) return Promise.resolve(engine)
          if (engineLoading !== null) return engineLoading
          engineLoading = (async () => {
            const [dicText, affText, freqText] = await Promise.all([
              gunzipText(DIC_GZ_BASE64),
              gunzipText(AFF_GZ_BASE64),
              gunzipText(FREQ_GZ_BASE64),
            ])
            engine = createEngine({
              dic: dicText,
              aff: affText,
              frequency: freqText.split('\n').filter(Boolean),
              userWords,
              ignore: ignoredWords,
            })
            const stats = engine.stats()
            console.info(`[dsh-spellcheck] dictionary ready: ${stats.stems} stems, ${stats.rules} rules, ${freqText.length} bytes of frequency data`)
            scheduleScan(0)
          })().catch((error) => {
            engineLoading = null
            console.warn('[dsh-spellcheck] dictionary failed to load', error)
          })
          return engineLoading
        }

        /** Запланировать пересканирование с ограничением частоты. */
        function scheduleScan(delay = SCAN_INTERVAL_MS) {
          if (disposed) return
          if (scanTimer !== 0) return
          const wait = Math.max(delay, lastScanAt + SCAN_INTERVAL_MS - Date.now())
          scanTimer = window.setTimeout(() => {
            scanTimer = 0
            lastScanAt = Date.now()
            try {
              scanChat()
            } catch (error) {
              console.warn('[dsh-spellcheck] scan failed', error)
            }
          }, Math.max(0, wait))
        }

        /** Узел находится в проверяемой области: лента чата или поле ввода. */
        function isCheckableTextNode(node) {
          const parent = node.parentElement
          if (!parent) return false
          if (parent.closest(SKIP_SELECTOR) !== null) return false
          return parent.closest(CHAT_REGION_SELECTOR) !== null
            || parent.closest(COMPOSER_INPUT_SELECTOR) !== null
        }

        /** Хост композера для узла, если это поле ввода. */
        function composerHostOf(node) {
          const parent = node.parentElement
          return parent === null ? null : parent.closest(COMPOSER_INPUT_SELECTOR)
        }

        /**
         * Отключить встроенную проверку Chromium в поле ввода.
         *
         * Иначе на одном слове рисуются две разные волны (своя и браузерная), а
         * нативное меню DSH не содержит вариантов замены. Свою проверку мы
         * включаем только после того, как словарь загрузился, поэтому при
         * сбое загрузки поведение остаётся штатным.
         */
        function silenceNativeSpelling() {
          for (const host of document.querySelectorAll(COMPOSER_INPUT_SELECTOR)) {
            if (host.getAttribute('spellcheck') === 'false') continue
            if (!nativeSpellingDisabled.has(host)) {
              nativeSpellingDisabled.set(host, host.getAttribute('spellcheck'))
            }
            host.setAttribute('spellcheck', 'false')
            if (!announcedSpellingOff) {
              announcedSpellingOff = true
              console.info('[dsh-spellcheck] composer found: built-in Chromium spellcheck disabled for it')
            }
          }
        }

        /** Вернуть исходный атрибут spellcheck (при выгрузке плагина). */
        function restoreNativeSpelling() {
          for (const [host, previous] of nativeSpellingDisabled) {
            if (!host.isConnected) continue
            if (previous === null) host.removeAttribute('spellcheck')
            else host.setAttribute('spellcheck', previous)
          }
          nativeSpellingDisabled.clear()
        }

        /** Пересчитать подсветку во всём чате. */
        function scanChat() {
          if (disposed || engine === null) return
          // Своя проверка готова — убираем конкурирующую браузерную в поле ввода.
          silenceNativeSpelling()
          const roots = [...document.querySelectorAll(CHAT_REGION_SELECTOR)]
          // Поле ввода обычно лежит внутри области чата, но могло быть отрисовано
          // и отдельно (портал/другая вёрстка): тогда обходим его как свой корень.
          for (const host of document.querySelectorAll(COMPOSER_INPUT_SELECTOR)) {
            const inside = roots.some(root => typeof root.contains === 'function' && root.contains(host))
            if (!inside) roots.push(host)
          }
          if (roots.length === 0) {
            // Чат не отрисован (стартовый экран): снимаем набор, чтобы не
            // держать ссылки на отключённые узлы.
            if (painted && highlightSupported()) CSS.highlights.delete(HIGHLIGHT_NAME)
            painted = false
            return
          }
          const ranges = []
          let recomputed = false
          for (const root of roots) {
            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
              acceptNode(node) {
                return isCheckableTextNode(node) && node.nodeValue && node.nodeValue.length >= 3
                  ? NodeFilter.FILTER_ACCEPT
                  : NodeFilter.FILTER_REJECT
              },
            })
            let node = walker.nextNode()
            while (node !== null) {
              if (collectNodeRanges(node, ranges)) recomputed = true
              node = walker.nextNode()
            }
          }
          // Пока текст не менялся, набор диапазонов тот же: повторная установка
          // заставила бы браузер пересчитывать отрисовку подсветки на каждом
          // потоковом токене без пользы.
          if (!recomputed && painted) return
          painted = true
          if (highlightSupported()) {
            CSS.highlights.set(HIGHLIGHT_NAME, new window.Highlight(...ranges))
          } else if (!warnedUnsupported) {
            warnedUnsupported = true
            console.warn('[dsh-spellcheck] CSS Custom Highlight API недоступен: подсветка отключена, меню работает по правому клику')
          }
        }

        /**
         * Собрать диапазоны ошибочных слов одного текстового узла (с кэшем).
         * @returns {boolean} пересчитывался ли узел (false — попали в кэш).
         */
        function collectNodeRanges(node, ranges) {
          const text = node.nodeValue || ''
          const cached = nodeCache.get(node)
          if (cached !== undefined && cached.text === text) {
            for (const range of cached.ranges) ranges.push(range)
            return false
          }
          const rangesOfNode = []
          for (const token of tokenize(text)) {
            if (!engine.shouldFlag(token.word)) continue
            const range = document.createRange()
            range.setStart(node, token.start)
            range.setEnd(node, token.end)
            rangesOfNode.push(range)
            ranges.push(range)
          }
          nodeCache.set(node, { text, ranges: rangesOfNode })
          return true
        }

        /**
         * Найти слово под указателем мыши.
         * @returns {null | { node: Text, start: number, end: number, word: string }}
         */
        function wordAtPoint(x, y) {
          const position = typeof document.caretRangeFromPoint === 'function'
            ? document.caretRangeFromPoint(x, y)
            : null
          if (!position) return null
          const node = position.startContainer
          if (node === null || node.nodeType !== Node.TEXT_NODE) return null
          if (!isCheckableTextNode(node)) return null
          const text = node.nodeValue || ''
          const offset = position.startOffset
          for (const token of tokenize(text)) {
            if (offset < token.start || offset > token.end) continue
            return { node, ...token }
          }
          return null
        }

        /**
         * Применить выбранное исправление к показанному тексту.
         *
         * Два пути:
         *  - лента чата: текст принадлежит React, поэтому меняем текстовый узел
         *    (правка живёт до перерисовки сообщения);
         *  - поле ввода: там contenteditable под управлением Lexical, поэтому
         *    слово выделяется и заменяется штатной командой редактирования —
         *    модель редактора остаётся согласованной.
         * @returns {{ ok: boolean, composer: boolean }} результат и место правки.
         */
        function applyFix(target, replacement) {
          if (!target || !target.node) return { ok: false, composer: false }
          const { node } = target
          if (!node.isConnected) return { ok: false, composer: false }
          const text = node.nodeValue || ''
          // Проверяем, что по сохранённым смещениям всё ещё то же слово:
          // за время между кликом и выбором пункта текст мог перерисоваться.
          const current = tokenize(text).find(token => token.start === target.start && token.end === target.end)
          if (!current) return { ok: false, composer: false }
          const display = matchCase(current.word, replacement)
          if (display === current.word) return { ok: false, composer: false }
          const composerHost = composerHostOf(node)
          if (composerHost !== null) {
            return { ok: applyComposerFix(composerHost, node, current, display), composer: true }
          }
          node.nodeValue = text.slice(0, current.start) + display + text.slice(current.end)
          lastFix = { node, start: current.start, length: display.length, from: current.word, to: display }
          nodeCache.delete(node)
          scheduleScan(0)
          return { ok: true, composer: false }
        }

        /**
         * Заменить слово в поле ввода через обычное редактирование.
         *
         * Выделяем слово в текстовом узле и вызываем execCommand('insertText'):
         * Chromium присылает beforeinput, Lexical применяет вставку штатным
         * путём, и модель редактора (а значит, и отправляемый текст) обновляется.
         * Если команда не сработала, текст остаётся прежним — портить ввод нельзя.
         * @param {Element} host - contenteditable композера.
         * @param {Text} node - текстовый узел со словом.
         * @param {{ start: number, end: number, word: string }} token - слово в узле.
         * @param {string} display - замена с нужным регистром.
         * @returns {boolean}
         */
        function applyComposerFix(host, node, token, display) {
          const selection = window.getSelection()
          if (selection === null) return false
          const range = document.createRange()
          range.setStart(node, token.start)
          range.setEnd(node, token.end)
          try {
            if (typeof host.focus === 'function') host.focus({ preventScroll: true })
            selection.removeAllRanges()
            selection.addRange(range)
            const applied = document.execCommand('insertText', false, display)
            nodeCache.delete(node)
            scheduleScan(0)
            return applied === true
          } catch (error) {
            console.warn('[dsh-spellcheck] composer replacement failed', error)
            return false
          }
        }

        /** Отменить последнее исправление в показанном тексте. */
        function undoLastFix() {
          const fix = lastFix
          if (fix === null) return
          lastFix = null
          const node = fix.node
          if (node.isConnected && node.nodeValue
            && node.nodeValue.slice(fix.start, fix.start + fix.length) === fix.to) {
            const text = node.nodeValue
            node.nodeValue = text.slice(0, fix.start) + fix.from + text.slice(fix.start + fix.length)
            nodeCache.delete(node)
          }
          scheduleScan(0)
        }

        /**
         * Показать уведомление хоста.
         * @param {string} from - исходное слово.
         * @param {string} to - выбранная замена.
         * @param {boolean} canUndo - предлагать ли отмену (в поле ввода отмена
         *   живёт в самом редакторе: Ctrl+Z и так работает).
         */
        function notifyFixed(from, to, canUndo) {
          const text = `${t('fixedNotice')}: «${from}» → «${to}»`
          if (!canUndo) {
            ctx.contextMenus.notify(text, true)
            return
          }
          ctx.contextMenus.notify(text, true, {
            label: t('undo'),
            run: () => { undoLastFix() },
            failureLabel: t('failed'),
          })
        }

        /** Запомнить слово в пользовательском словаре и сохранить его. */
        function addUserWord(word) {
          const lower = word.toLowerCase()
          if (userWords.has(lower)) return
          userWords.add(lower)
          if (engine !== null) engine.addUserWord(lower)
          writeStoredList(STORAGE_USER, [...userWords])
          resetNodeCache()
          scheduleScan(0)
        }

        /**
         * Действия контекстного меню для конкретного слова.
         * @param {{ word: string, occurrence?: string }} value - цель из ctx.contextMenus.open.
         */
        function menuActions(value) {
          if (engine === null) {
            void ensureEngine()
            return [{ id: 'loading', label: t('unavailable'), disabled: true }]
          }
          const word = String(value && value.word ? value.word : '')
          if (word === '') return []
          const target = occurrences.get(String(value && value.occurrence ? value.occurrence : '')) ?? null
          /** @type {Array<{id: string, label: string, run?: () => void, disabled?: boolean, separatorBefore?: boolean}>} */
          const actions = []
          // Не больше пяти вариантов: длинный список превращает меню в свалку,
          // а первые кандидаты и так самые правдоподобные.
          const suggestions = engine.suggest(word).slice(0, MAX_MENU_SUGGESTIONS)
          if (suggestions.length > 0) {
            actions.push({ id: 'suggest-header', label: t('suggestHeader'), disabled: true })
            for (let index = 0; index < suggestions.length; index += 1) {
              const suggestion = suggestions[index]
              actions.push({
                id: `apply-${index}`,
                label: suggestion.word,
                run: () => {
                  const result = target === null
                    ? { ok: false, composer: false }
                    : applyFix(target, suggestion.word)
                  if (result.ok) {
                    console.info(`[dsh-spellcheck] fixed «${word}» → «${matchCase(word, suggestion.word)}» in ${result.composer ? 'composer' : 'transcript'}`)
                    notifyFixed(word, matchCase(word, suggestion.word), !result.composer)
                  } else {
                    // Текст перерисовался между кликом и выбором: молчать нельзя,
                    // иначе выглядит как поломка.
                    ctx.contextMenus.notify(t('failed'))
                  }
                  occurrences.delete(String(value.occurrence ?? ''))
                },
              })
            }
          }
          actions.push({
            id: 'add-dictionary',
            label: t('addToDictionary'),
            separatorBefore: suggestions.length > 0,
            run: () => { addUserWord(word) },
          })
          actions.push({
            id: 'ignore-session',
            label: t('ignoreSession'),
            run: () => {
              ignoredWords.add(word.toLowerCase())
              if (engine !== null) engine.addIgnored(word.toLowerCase())
              // Кэш диапазонов помнит прежнее решение для этого узла, поэтому
              // сбрасываем его целиком: иначе подчёркивание останется висеть.
              resetNodeCache()
              scheduleScan(0)
            },
          })
          return actions
        }

        /**
         * Открыть меню хоста для найденного слова и запомнить жест.
         * @param {{ node: Text, start: number, end: number, word: string }} target
         * @param {{ x: number, y: number }} point
         */
        function openWordMenu(target, point) {
          occurrenceSeq += 1
          const occurrence = String(occurrenceSeq)
          occurrences.set(occurrence, target)
          // Карта не должна расти: держим только последние вхождения.
          if (occurrences.size > 20) occurrences.delete(occurrences.keys().next().value)
          lastOpen = { word: target.word, at: Date.now() }
          console.info(`[dsh-spellcheck] menu for «${target.word}» in ${composerHostOf(target.node) === null ? 'transcript' : 'composer'}`)
          ctx.contextMenus.open(
            { kind: TARGET_KIND, value: { word: target.word, occurrence } },
            point,
          )
        }

        /**
         * Правый клик на уровне указателя.
         *
         * Нативное меню Electron приходит из главного процесса и не всегда
         * уважает preventDefault на contextmenu, поэтому жест отменяется ещё
         * здесь: у Chromium это надёжно убирает и нативное меню, и выделение
         * слова под курсором.
         */
        function onPointerDown(event) {
          if (disposed || engine === null || event.button !== 2) return
          const target = wordAtPoint(event.clientX, event.clientY)
          if (target === null) return
          if (!engine.shouldFlag(target.word)) return
          event.preventDefault()
          openWordMenu(target, { x: event.clientX, y: event.clientY })
        }

        /** Обработчик contextmenu: клавиатура и случаи, когда pointerdown не пришёл. */
        function onContextMenu(event) {
          if (disposed || engine === null) return
          const target = wordAtPoint(event.clientX, event.clientY)
          if (target === null) return
          if (!engine.shouldFlag(target.word)) return
          // preventDefault обязателен: иначе штатный обработчик хоста закроет
          // уже открытое меню (он реагирует на неотменённый contextmenu).
          event.preventDefault()
          // Меню уже открыто обработчиком pointerdown. Повторный open() по тому
          // же слову хост понял бы как повторный жест и закрыл меню.
          if (lastOpen.word === target.word && Date.now() - lastOpen.at < 500) return
          openWordMenu(target, { x: event.clientX, y: event.clientY })
        }

        /** Запуск: стили, наблюдатели, отложенная загрузка словаря. */
        function start() {
          if (typeof CSS === 'undefined' || !CSS.highlights) {
            // Без подсветки меню по правому клику всё равно полезно, поэтому
            // продолжаем работу, только предупреждаем один раз.
            console.warn('[dsh-spellcheck] CSS.highlights недоступен: подчёркивание не будет показано')
          }
          // Стиль добавляется в head; если документа ещё нет (теоретически при
          // очень ранней активации), плагин не должен падать внутри хоста.
          try {
            if (document.head) document.head.appendChild(styleElement)
          } catch (error) {
            console.warn('[dsh-spellcheck] style injection failed', error)
          }
          try {
            observer = new MutationObserver(() => { scheduleScan() })
            observer.observe(document.body, { childList: true, subtree: true, characterData: true })
          } catch (error) {
            console.warn('[dsh-spellcheck] observer setup failed', error)
          }
          document.addEventListener('pointerdown', onPointerDown, true)
          document.addEventListener('contextmenu', onContextMenu, true)
          // Словарь грузим сразу, но не блокируя первый кадр интерфейса.
          // Хэндл таймера храним: иначе после выгрузки плагина словарь всё
          // равно распакуется и соберётся (сотни миллисекунд на главном потоке).
          loadTimer = window.setTimeout(() => {
            loadTimer = 0
            void ensureEngine()
          }, 150)
          return () => {
            disposed = true
            if (scanTimer !== 0) window.clearTimeout(scanTimer)
            scanTimer = 0
            if (loadTimer !== 0) window.clearTimeout(loadTimer)
            loadTimer = 0
            occurrences.clear()
            restoreNativeSpelling()
            observer?.disconnect()
            observer = null
            document.removeEventListener('pointerdown', onPointerDown, true)
            document.removeEventListener('contextmenu', onContextMenu, true)
            styleElement.remove()
            if (highlightSupported()) CSS.highlights.delete(HIGHLIGHT_NAME)
          }
        }

        ctx.effect(() => ctx.locale.register(NAMESPACE, DICTIONARIES), 'spellcheck: locale')
        ctx.effect(() => ctx.contextMenus.register({
          id: 'dsh-spellcheck',
          target: TARGET_KIND,
          order: 0,
          resolve: value => menuActions(value),
        }), 'spellcheck: context menu')
        ctx.effect(start, 'spellcheck: highlight lifetime')

        // Отладочный доступ для тестов сборки: сами тесты выполняются в Node
        // и вызывают чистые функции ядра, здесь же проверяется только то, что
        // фабрика собралась и экспортирует ожидаемый контракт.
        if (typeof globalThis === 'object' && globalThis.__DSH_SPELLCHECK_PROBE__ === true) {
          globalThis.__dshSpellcheck = {
            apply: pluginHandle?.apply,
            tokenize,
            matchCase,
            wordKey,
            NAMESPACE,
            TARGET_KIND,
            HIGHLIGHT_NAME,
          }
        }
      },
    }
    pluginHandle = plugin
    return plugin
  },
})
